package review

import (
	"context"
	"errors"
	"fmt"
	"sort"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
	"github.com/entireio/cli/cmd/entire/cli/settings"
)

const DefaultProfileName = "general"

const (
	defaultGeneralTask       = "Review this change for correctness, regressions, API design, missing tests, maintainability, and user-facing behavior changes. Report only actionable findings with concrete evidence."
	defaultSecurityTask      = "Review this change for security vulnerabilities: authentication and authorization bugs, injection risks, secrets exposure, unsafe dependency or deserialization behavior, privilege-boundary mistakes, insecure defaults, and data leakage. Report only actionable findings with concrete evidence."
	defaultAccessibilityTask = "Review this change for accessibility regressions: keyboard navigation, focus management, semantic markup, labels, ARIA correctness, color contrast, reduced-motion behavior, screen-reader behavior, and inclusive error states. Report only actionable findings with concrete evidence."
)

// profileTask returns the configured task, or a built-in task for conventional
// profile names when the config leaves task empty.
func profileTask(name string, cfg settings.ReviewProfileConfig) string {
	if strings.TrimSpace(cfg.Task) != "" {
		return strings.TrimSpace(cfg.Task)
	}
	switch strings.ToLower(name) {
	case "", DefaultProfileName:
		return defaultGeneralTask
	case "security":
		return defaultSecurityTask
	case "accessibility", "a11y":
		return defaultAccessibilityTask
	default:
		return defaultGeneralTask
	}
}

// selectReviewProfile resolves the profile to run. No legacy fallback is used:
// users must configure review_profiles (the command is experimental, so there
// is intentionally no migration from the old review map).
func selectReviewProfile(s *settings.EntireSettings, override string) (string, settings.ReviewProfileConfig, error) {
	if s == nil || len(s.ReviewProfiles) == 0 {
		return "", settings.ReviewProfileConfig{}, errors.New("no review profiles configured; run `entire inspect --configure` or add review_profiles to Entire preferences")
	}
	profiles := nonZeroProfiles(s.ReviewProfiles)
	if len(profiles) == 0 {
		return "", settings.ReviewProfileConfig{}, errors.New("no review profiles configured; every profile is empty")
	}

	name := strings.TrimSpace(override)
	if name == "" {
		name = strings.TrimSpace(s.ReviewDefaultProfile)
	}
	if name == "" {
		if _, ok := profiles[DefaultProfileName]; ok {
			name = DefaultProfileName
		} else if len(profiles) == 1 {
			for only := range profiles {
				name = only
			}
		} else {
			return "", settings.ReviewProfileConfig{}, fmt.Errorf(
				"multiple review profiles configured (%s); pass a profile name or set review_default_profile",
				strings.Join(sortedProfileNames(profiles), ", "))
		}
	}

	cfg, ok := profiles[name]
	if !ok {
		return "", settings.ReviewProfileConfig{}, fmt.Errorf(
			"review profile %q is not configured; configured profiles: %s",
			name, strings.Join(sortedProfileNames(profiles), ", "))
	}
	if len(nonZeroAgentConfigs(cfg.Agents)) == 0 {
		return "", settings.ReviewProfileConfig{}, fmt.Errorf("review profile %q has no configured agents", name)
	}
	return name, cfg, nil
}

func nonZeroProfiles(in map[string]settings.ReviewProfileConfig) map[string]settings.ReviewProfileConfig {
	out := make(map[string]settings.ReviewProfileConfig, len(in))
	for name, cfg := range in {
		name = strings.TrimSpace(name)
		if name == "" || cfg.IsZero() {
			continue
		}
		out[name] = cfg
	}
	return out
}

func sortedProfileNames(in map[string]settings.ReviewProfileConfig) []string {
	names := make([]string, 0, len(in))
	for name := range in {
		names = append(names, name)
	}
	sort.Strings(names)
	return names
}

func nonZeroAgentConfigs(in map[string]settings.ReviewConfig) map[string]settings.ReviewConfig {
	out := make(map[string]settings.ReviewConfig, len(in))
	for name, cfg := range in {
		name = strings.TrimSpace(name)
		if name == "" || cfg.IsZero() {
			continue
		}
		out[name] = cfg
	}
	return out
}

func sortedProfileAgentNames(profile settings.ReviewProfileConfig) []string {
	names := make([]string, 0, len(profile.Agents))
	for name := range profile.Agents {
		names = append(names, name)
	}
	sort.Strings(names)
	return names
}

func reviewAgentName(workerName string, cfg settings.ReviewConfig) string {
	if strings.TrimSpace(cfg.Agent) != "" {
		return strings.TrimSpace(cfg.Agent)
	}
	return strings.TrimSpace(workerName)
}

func reviewWorkerLabel(workerName string, cfg settings.ReviewConfig) string {
	agentName := reviewAgentName(workerName, cfg)
	parts := []string{workerName}
	var details []string
	if agentName != "" && agentName != workerName {
		details = append(details, agentName)
	}
	if strings.TrimSpace(cfg.Model) != "" {
		details = append(details, "model "+strings.TrimSpace(cfg.Model))
	}
	if len(details) > 0 {
		parts = append(parts, "  ("+strings.Join(details, ", ")+")")
	}
	return strings.Join(parts, "")
}

// judgeSpec is one resolved judge: the agent that renders a verdict plus its
// optional model.
type judgeSpec struct {
	agent string
	model string
}

// profileJudges resolves the panel of judges and the index of the chair (the
// judge that merges a multi-judge panel; 0 for a single judge). Resolution
// order: explicit Judges, then the legacy standalone MasterAgent, then the
// legacy worker Master. Returns an empty slice when the profile has no judge.
func profileJudges(profile settings.ReviewProfileConfig) ([]judgeSpec, int) {
	if len(profile.Judges) > 0 {
		judges := make([]judgeSpec, 0, len(profile.Judges))
		for _, cfg := range profile.Judges {
			name := strings.TrimSpace(cfg.Agent)
			if name == "" {
				continue
			}
			judges = append(judges, judgeSpec{agent: name, model: strings.TrimSpace(cfg.Model)})
		}
		if len(judges) == 0 {
			return nil, 0
		}
		chair := 0
		if sel := strings.TrimSpace(profile.Chair); sel != "" {
			for i, j := range judges {
				if j.agent == sel || j.agent+":"+j.model == sel {
					chair = i
					break
				}
			}
		}
		return judges, chair
	}
	if ma := strings.TrimSpace(profile.MasterAgent); ma != "" {
		return []judgeSpec{{agent: ma, model: strings.TrimSpace(profile.MasterModel)}}, 0
	}
	if workerName, cfg, err := selectProfileWorker(profile, profile.Master); err == nil {
		model := strings.TrimSpace(profile.MasterModel)
		if model == "" {
			model = strings.TrimSpace(cfg.Model)
		}
		return []judgeSpec{{agent: reviewAgentName(workerName, cfg), model: model}}, 0
	}
	return nil, 0
}

// profileMasterIdentity reports the representative judge (the chair, or the
// single judge) and whether the profile has any judge. Kept for callers that
// need a single "who decides" identity (validation, labels, picker preselect).
func profileMasterIdentity(profile settings.ReviewProfileConfig) (string, string, bool) {
	judges, chair := profileJudges(profile)
	if len(judges) == 0 {
		return "", "", false
	}
	if chair < 0 || chair >= len(judges) {
		chair = 0
	}
	return judges[chair].agent, judges[chair].model, true
}

// judgeLabel renders a judge for UI output: "agent" or "agent · model".
func judgeLabel(j judgeSpec) string {
	if strings.TrimSpace(j.model) != "" {
		return labelForSimpleAgent(j.agent) + " · " + j.model
	}
	return labelForSimpleAgent(j.agent)
}

func selectProfileWorker(profile settings.ReviewProfileConfig, selector string) (string, settings.ReviewConfig, error) {
	selector = strings.TrimSpace(selector)
	if selector == "" {
		return "", settings.ReviewConfig{}, errors.New("empty review inspector selector")
	}
	if cfg, ok := profile.Agents[selector]; ok && !cfg.IsZero() {
		return selector, cfg, nil
	}
	var matches []string
	for workerName, cfg := range profile.Agents {
		if cfg.IsZero() {
			continue
		}
		if reviewAgentName(workerName, cfg) == selector {
			matches = append(matches, workerName)
		}
	}
	sort.Strings(matches)
	switch len(matches) {
	case 1:
		return matches[0], profile.Agents[matches[0]], nil
	case 0:
		configured := sortedProfileAgentNames(profile)
		if len(configured) == 0 {
			return "", settings.ReviewConfig{}, fmt.Errorf("review inspector or agent %q is not configured", selector)
		}
		return "", settings.ReviewConfig{}, fmt.Errorf("review inspector or agent %q is not configured; configured inspectors: %s", selector, strings.Join(configured, ", "))
	default:
		return "", settings.ReviewConfig{}, fmt.Errorf("agent %q has multiple review inspectors (%s); choose one by inspector name", selector, strings.Join(matches, ", "))
	}
}

func workerIDForAgentModel(agentName, model string, existing map[string]settings.ReviewConfig) string {
	base := strings.TrimSpace(agentName)
	if strings.TrimSpace(model) != "" {
		base += ":" + sanitizeWorkerIDPart(model)
	}
	if base == "" {
		base = "worker"
	}
	candidate := base
	for i := 2; ; i++ {
		if _, exists := existing[candidate]; !exists {
			return candidate
		}
		candidate = fmt.Sprintf("%s-%d", base, i)
	}
}

func sanitizeWorkerIDPart(s string) string {
	s = strings.ToLower(strings.TrimSpace(s))
	var b strings.Builder
	lastDash := false
	for _, r := range s {
		keep := (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9')
		if keep {
			b.WriteRune(r)
			lastDash = false
			continue
		}
		if !lastDash {
			b.WriteByte('-')
			lastDash = true
		}
	}
	out := strings.Trim(b.String(), "-")
	if out == "" {
		return "model"
	}
	return out
}

func defaultReviewProfileForInstalledAgents(
	ctx context.Context,
	profileName string,
	installed []types.AgentName,
	reviewerFor func(string) reviewtypes.AgentReviewer,
) (settings.ReviewProfileConfig, error) {
	profileName = strings.TrimSpace(profileName)
	if profileName == "" {
		profileName = DefaultProfileName
	}
	installedNames := make([]string, 0, len(installed))
	for _, name := range installed {
		installedNames = append(installedNames, string(name))
	}
	sort.Strings(installedNames)

	agents := make(map[string]settings.ReviewConfig, len(installedNames))
	for _, name := range installedNames {
		if reviewerFor != nil && reviewerFor(name) == nil {
			continue
		}
		cfg := defaultReviewAgentConfig(profileName, name)
		if cfg.IsZero() {
			continue
		}
		agents[name] = cfg
	}
	if len(agents) == 0 {
		return settings.ReviewProfileConfig{}, errors.New("no agents with review runner adapters and hooks installed; run `entire configure --agent claude-code`, `entire configure --agent codex`, or `entire configure --agent gemini`")
	}
	return settings.ReviewProfileConfig{
		Task:   profileTask(profileName, settings.ReviewProfileConfig{}),
		Agents: agents,
		Master: defaultReviewMaster(ctx, agents),
	}, nil
}

func defaultReviewAgentConfig(profileName, agentName string) settings.ReviewConfig {
	focus := defaultProfileFocus(profileName)
	switch agentName {
	case string(agent.AgentNameClaudeCode):
		if strings.EqualFold(profileName, "security") {
			return settings.ReviewConfig{Skills: []string{"/security-review"}}
		}
		return settings.ReviewConfig{Skills: []string{"/review"}, Prompt: focus}
	case string(agent.AgentNameCodex):
		return settings.ReviewConfig{Skills: []string{"/review"}, Prompt: focus}
	case string(agent.AgentNameGemini):
		prompt := "Review the change according to the profile task."
		if focus != "" {
			prompt += " " + focus
		}
		return settings.ReviewConfig{Prompt: prompt}
	default:
		return settings.ReviewConfig{}
	}
}

func defaultProfileFocus(profileName string) string {
	switch strings.ToLower(strings.TrimSpace(profileName)) {
	case "security":
		return "Focus specifically on security issues."
	case "accessibility", "a11y":
		return "Focus specifically on accessibility issues."
	default:
		return ""
	}
}

func defaultReviewMaster(ctx context.Context, configured map[string]settings.ReviewConfig) string {
	for _, preferred := range []string{string(agent.AgentNameClaudeCode), string(agent.AgentNameCodex), string(agent.AgentNameGemini)} {
		for _, workerName := range sortedReviewConfigKeys(configured) {
			cfg := configured[workerName]
			if reviewAgentName(workerName, cfg) == preferred && agentSupportsTextGeneration(ctx, preferred) {
				return workerName
			}
		}
	}
	for _, workerName := range sortedReviewConfigKeys(configured) {
		if agentSupportsTextGeneration(ctx, reviewAgentName(workerName, configured[workerName])) {
			return workerName
		}
	}
	return ""
}

func sortedReviewConfigKeys(configured map[string]settings.ReviewConfig) []string {
	names := make([]string, 0, len(configured))
	for name := range configured {
		names = append(names, name)
	}
	sort.Strings(names)
	return names
}

func agentSupportsTextGeneration(_ context.Context, name string) bool {
	ag, err := agent.Get(types.AgentName(name))
	if err != nil {
		return false
	}
	_, ok := agent.AsTextGenerator(ag)
	return ok
}

func saveDefaultReviewProfile(ctx context.Context, profileName string, profile settings.ReviewProfileConfig) error {
	return saveReviewProfile(ctx, profileName, profile, false)
}

func saveReviewProfile(ctx context.Context, profileName string, profile settings.ReviewProfileConfig, makeDefault bool) error {
	prefs, err := settings.LoadClonePreferences(ctx)
	if err != nil {
		return fmt.Errorf("load review preferences before save: %w", err)
	}
	if prefs == nil {
		prefs = &settings.ClonePreferences{}
	}
	if prefs.ReviewProfiles == nil {
		prefs.ReviewProfiles = map[string]settings.ReviewProfileConfig{}
	}
	prefs.ReviewProfiles[profileName] = profile
	if makeDefault || prefs.ReviewDefaultProfile == "" {
		prefs.ReviewDefaultProfile = profileName
	}
	if err := settings.SaveClonePreferences(ctx, prefs); err != nil {
		return fmt.Errorf("save review preferences: %w", err)
	}
	return nil
}

// Package review — see env.go for package-level rationale.
//
// synthesis_prompt.go builds the LLM prompt that asks a configured summary
// provider to synthesize a unified verdict across N per-agent review reports.
// It is a pure-function composer with no I/O; all logic is testable without
// network calls or TTY state.
package review

import (
	"fmt"
	"strings"

	reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
)

// composeSynthesisPrompt builds the LLM prompt asking the provider to
// synthesize a unified verdict across N agent reviews. Format:
//
//	You reviewed the same code change with N agents. Here are their reports:
//
//	─── claude-code ───
//	<narrative from agent's AssistantText events, joined>
//
//	─── codex ───
//	<narrative>
//
//	...
//
//	Synthesize a unified verdict with these sections:
//	  - Common findings (issues all agents flagged)
//	  - Unique findings (issues only one agent caught)
//	  - Disagreements (areas where agents reached different conclusions)
//	  - Priority order (top 5 issues to address first)
//
//	Be concise; aim for ~300 words.
//
//	<perRunPrompt, if any — appended as user's per-run instructions>
//
// Agents with no usable narrative (empty AssistantText) are filtered out
// upstream by usableAgentRuns, so the header count and the body are both
// scoped to agents that produced narrative output. SynthesisSink already
// guards on len(usable) >= 2 before calling, so the empty case won't reach
// the LLM in production.
func composeSynthesisPrompt(summary reviewtypes.RunSummary, perRunPrompt string, profileName string, task string) string {
	usable := usableAgentRuns(summary)
	if len(usable) == 0 {
		return ""
	}

	var b strings.Builder

	fmt.Fprintf(&b, "You reviewed the same code change with %d agents. You are the final reviewer; critically adjudicate their reports instead of blindly summarizing.\n", len(usable))
	if profileName != "" {
		fmt.Fprintf(&b, "Review profile: %s\n", profileName)
	}
	if strings.TrimSpace(task) != "" {
		fmt.Fprintf(&b, "Canonical task: %s\n", strings.TrimSpace(task))
	}
	b.WriteString("\nHere are their reports:\n")

	for _, run := range usable {
		narrative := joinAssistantText(run.Buffer)
		if narrative == "" {
			continue
		}
		fmt.Fprintf(&b, "\n─── %s ───\n", run.Name)
		b.WriteString(narrative)
		b.WriteString("\n")
	}

	b.WriteString(`
Critically evaluate the worker reports. Do not blindly summarize.

Rules:
  - Prefer findings backed by concrete evidence (file, function, behavior, test, or diff detail).
  - Discard unsupported or speculative claims unless they are clearly labeled as needing verification.
  - Identify contradictions between workers and decide which claim is better supported.
  - Merge duplicate findings.
  - Call out important uncertainty instead of pretending certainty.

Produce one canonical final report with these sections:
  - Executive verdict
  - Common findings / high-confidence findings, prioritized
  - Unique findings worth keeping
  - Needs verification / uncertain findings
  - Disagreements or rejected false positives
  - Priority order / recommended next actions

Be concise but specific; include evidence pointers where available.`)

	if perRunPrompt != "" {
		b.WriteString("\n\nPer-run user instructions:\n")
		b.WriteString(perRunPrompt)
	}

	return b.String()
}

// usableAgentRuns returns agent runs that have non-empty AssistantText
// narrative in their event buffer, in the original order from the summary.
// The filter is on narrative content alone — Status is not checked. In
// practice this drops most cancelled and errored runs (they typically don't
// produce assistant output before exiting), but a cancelled agent that
// emitted text mid-stream is still considered usable. The synthesis prompt
// uses what the agent actually said, regardless of how the run terminated.
func usableAgentRuns(summary reviewtypes.RunSummary) []reviewtypes.AgentRun {
	var result []reviewtypes.AgentRun
	for _, run := range summary.AgentRuns {
		if joinAssistantText(run.Buffer) == "" {
			continue
		}
		result = append(result, run)
	}
	return result
}

package review

import (
	"context"
	"errors"
	"fmt"
	"strings"
	"sync"
)

// PanelSynthesisProvider runs a panel of judges over the inspectors' reports.
// Each judge independently produces a verdict from the same synthesis prompt;
// when two or more verdicts come back, the chair judge merges them into one
// final verdict and the individual verdicts are appended as a panel.
//
// It implements SynthesisProvider, so the existing SynthesisSink uses it
// unchanged — a panel is just a provider that happens to consult several
// judges. A single judge collapses to that judge's verdict (today's behavior).
type PanelSynthesisProvider struct {
	Judges   []SynthesisProvider // one per judge; index aligns with Labels
	Labels   []string            // display label per judge (e.g. "codex · gpt-5")
	ChairIdx int                 // index of the judge that merges the panel
}

// Synthesize fans out to each judge in parallel, then has the chair merge the
// verdicts. Failed judges are dropped; if only one verdict survives it is
// returned directly. If every judge fails, the error is returned so the caller
// can report "final report unavailable".
func (p PanelSynthesisProvider) Synthesize(ctx context.Context, prompt string) (string, error) {
	switch len(p.Judges) {
	case 0:
		return "", errors.New("no judges configured")
	case 1:
		return p.Judges[0].Synthesize(ctx, prompt) //nolint:wrapcheck // transparent single-judge passthrough
	}

	verdicts := make([]string, len(p.Judges))
	errs := make([]error, len(p.Judges))
	var wg sync.WaitGroup
	for i := range p.Judges {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			verdicts[i], errs[i] = p.Judges[i].Synthesize(ctx, prompt)
		}(i)
	}
	wg.Wait()

	ok := make([]int, 0, len(p.Judges))
	for i := range verdicts {
		if errs[i] == nil && strings.TrimSpace(verdicts[i]) != "" {
			ok = append(ok, i)
		}
	}
	switch len(ok) {
	case 0:
		return "", fmt.Errorf("all judges failed: %w", firstNonNilErr(errs))
	case 1:
		return verdicts[ok[0]], nil
	}

	// Pick the chair; fall back to the first successful judge if the configured
	// chair failed or is out of range. The chair participates as a full panel
	// judge (it produced its own verdict above) and then runs a second time to
	// merge the panel — these are deliberately distinct calls: an independent
	// verdict, then a reconciliation over all verdicts.
	chair := p.ChairIdx
	if chair < 0 || chair >= len(p.Judges) || errs[chair] != nil || strings.TrimSpace(verdicts[chair]) == "" {
		chair = ok[0]
	}

	final, err := p.Judges[chair].Synthesize(ctx, composeChairPrompt(verdicts, p.Labels, ok))
	if err != nil || strings.TrimSpace(final) == "" {
		// Chair merge failed: surface the panel rather than nothing.
		final = "The judges could not be merged into a single verdict; see each judge's verdict below."
	}

	var b strings.Builder
	b.WriteString(strings.TrimSpace(final))
	b.WriteString("\n\n## Panel\n\n")
	for _, i := range ok {
		fmt.Fprintf(&b, "### %s\n\n%s\n\n", p.labelAt(i), strings.TrimSpace(verdicts[i]))
	}
	return b.String(), nil
}

func (p PanelSynthesisProvider) labelAt(i int) string {
	if i >= 0 && i < len(p.Labels) && strings.TrimSpace(p.Labels[i]) != "" {
		return p.Labels[i]
	}
	return fmt.Sprintf("judge %d", i+1)
}

// composeChairPrompt instructs the chair judge to reconcile the panel's
// verdicts into one final verdict, explicitly surfacing agreement and dissent.
func composeChairPrompt(verdicts, labels []string, ok []int) string {
	var b strings.Builder
	b.WriteString("You are the presiding judge on a panel reviewing a code change. " +
		"Several judges independently evaluated the inspectors' reports and produced the verdicts below. " +
		"Write a single final verdict that reconciles them: state the decision, " +
		"explicitly call out where the judges AGREED and where they DISAGREED, and " +
		"resolve disagreements on the merits (note which judge is right and why). " +
		"Do not simply concatenate the verdicts.\n\n")
	for _, i := range ok {
		label := fmt.Sprintf("judge %d", i+1)
		if i < len(labels) && strings.TrimSpace(labels[i]) != "" {
			label = labels[i]
		}
		fmt.Fprintf(&b, "## Verdict from %s\n\n%s\n\n", label, strings.TrimSpace(verdicts[i]))
	}
	return b.String()
}

func firstNonNilErr(errs []error) error {
	for _, e := range errs {
		if e != nil {
			return e
		}
	}
	return errors.New("unknown synthesis error")
}

// Compile-time check.
var _ SynthesisProvider = PanelSynthesisProvider{}

